sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {
	var template_id = target.getValue('x_mioms_azpipeline_template_id');
	var number = target.getValue("number");
	var correlation_id = target.getValue("correlation_id");
	var logId = correlation_id;
	if (number) {
		logId = number;
	}
	if (!template_id) {
		gs.info("["+logId+"][OnComplete TransformRule] No Template Id Found on Target Table so skipping");
		return;
	}
	var template = new GlideRecord('sys_template');
	gs.info("["+logId+"][OnComplete TransformRule] Executing Apply template After BR");
	if(template.get(template_id)){
		gs.info("["+logId+"][OnComplete TransformRule]Applying child template :"+template_id);
		applyChildTemplates(target.getRecordClassName(),target.getUniqueValue(), template.getValue('next_child'));
	}

	function applyChildTemplates(parentTable, parentID, nextID){
		gs.info("["+logId+"][OnComplete TransformRule]NextID :"+ nextID);
		while (nextID) {
			var childtemplate = new GlideRecord('sys_template');
			if(childtemplate.get(nextID)){
				var childGR = new GlideRecord(childtemplate.getValue('table'));
				childGR.initialize();
				var templateArray = childtemplate.template.toString().split('^');
				for(var i=0; i<templateArray.length; i++){
					var templatefield = templateArray[i].toString().split('=');
					if(templatefield != 'EQ'){
						// childGR[templatefield[0]] = templatefield[1].toString();
						childGR.setValue(templatefield[0], templatefield[1].toString());
					}
				}
				// childGR[parentTable] = parentID.toString();
				childGR.setValue(parentTable, parentID.toString());
				var templateDetails = new GlideRecord('std_change_record_producer');
				if (templateDetails.get('template', nextID)) {
					var currentVersion = templateDetails.getElement('current_version');
					if(currentVersion){
						gs.info("["+logId+"][OnComplete TransformRule]Current Version is :"+ currentVersion);
						childGR.setValue("std_change_producer_version", currentVersion);
					} else {
						gs.info("["+logId+"][OnComplete TransformRule]Current version is empty");
					}
				} else {
					gs.info("["+logId+"][OnComplete TransformRule]Version information is not there :"+ nextID);
				}
				childGR.insert();
				gs.info("["+logId+"][OnComplete TransformRule]Inserted child record");
				var childID = childtemplate.getValue('next_child');
				if (childID) {
					gs.info("["+logId+"][OnComplete TransformRule]Applying template to next child");
					applyChildTemplates(childGR.getTableName(), childGR.getUniqueValue(), childID);
				}

				nextID = childtemplate.getValue('next');
			}else
				break;
		}
	}

})(source, map, log, target);
